_year": 1390, "end_year": 1390, "time_original": "洪武二十三年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f051fd86-2869-5e57-a1ec-18224cb57ab2"}, {"title": "潭王朱梓自焚身亡", "description": "本纪记载，潭王朱梓自焚身亡。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年四月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b4ca7b99-136a-5af1-8966-82dd3d4dbaec"}, {"title": "蓝玉平定施南忠建战事", "description": "蓝玉率军平定施南、忠建的战事。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年闰四月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec8d898a-1ba8-5108-8f6f-e900ed823222"}, {"title": "明廷遣诸公侯还乡并给赏赐", "description": "朝廷遣诸公侯返回家乡，分别赏赐金和财帛。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e59a2e27-4bb2-5ca7-8daa-89148d80a7fd"}, {"title": "李善长被赐死，陆仲亨等被处死", "description": "朝廷赐太师、韩国公李善长死，陆仲亨等也因涉案被处死。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年五月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e17802f1-d5e4-51e6-9ab3-3559ec9567e0"}, {"title": "明廷编制并公布《昭示奸党录》", "description": "朝廷编制《昭示奸党录》，向天下公布。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "71cbc8af-dec3-5e17-a2cc-8307f5d90974"}, {"title": "蓝玉派张龙平定都匀等地战事", "description": "蓝玉派凤翔侯张龙率军，平定都匀、散毛等地的战事。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年六月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "409849d1-ac7d-54f0-a04c-1cba4389162b"}, {"title": "明廷授官给有才德且熟悉典故的长者", "description": "朝廷挑选有才德、熟悉典章旧事的年长百姓，授予官职。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年六月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "68e14065-0be5-5f83-817e-b5b5c057a7fa"}, {"title": "黄河在开封决口，明廷下令赈济", "description": "黄河在开封决口，朝廷下令赈济灾民。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年七月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1cf50ae-74fa-5fcb-afc2-6cc505d0183a"}, {"title": "明廷赈济崇明海门并调民修堤", "description": "崇明和海门遭遇风雨和海水漫溢。朝廷派官员救济，征调二十五万民众修筑堤坝。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年七月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dd571f43-cc42-52d8-a291-a518197a7451"}, {"title": "明廷禁止让吏卒充当荐举人选", "description": "朝廷下诏，地方荐举人才时不得以吏卒充数。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十三年八月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b9c3d49-44b6-59ce-8275-f3d18b3e2