": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4efc29b8-f20d-5c5f-8259-5138047163dc"}, {"title": "明廷停止每年织造文绮的规定", "description": "朝廷停止各地每年织造花纹丝织品的规定。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十三年十二月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "957a2a12-866b-5c0f-a8a6-a64a9d365378"}, {"title": "墨剌等地来贡", "description": "本纪记载，墨剌、哈梅里、高丽、占城、真腊、琉球和暹罗于当年来贡。 按原历纪年，事情发生在公元1390至1391年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b3edb7e4-d94c-5801-bcdd-1c4b99baf761"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年正月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b1be28bd-e23a-5a17-8ba6-881e7ac5e28b"}, {"title": "傅友德王弼郭英奉命守备北平边地", "description": "颍国公傅友德任征虏将军，定远侯王弼、武定侯郭英任副将，在北平布置边防。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年正月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ad76d06-8aaa-57c5-ae6f-f929a713e05b"}, {"title": "明廷免征山东田租", "description": "朝廷免去山东田租。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年正月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34edb8c8-2dae-56fc-997d-10099cdb2e89"}, {"title": "朱元璋行耕耤礼", "description": "朱元璋举行亲耕耤田的仪式。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年二月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "992baa83-c12a-5533-949a-13b8bf34857e"}, {"title": "本纪记三月初一日食", "description": "本纪记载，三月初一出现日食。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年三月戊子朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "026c8238-25db-5f31-9f37-29ac8f14af5f"}, {"title": "徐辉祖李景隆蓝玉等在陕西备边", "description": "魏国公徐辉祖、曹国公李景隆、凉国公蓝玉等人在陕西部署边防。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "08f7689c-f936-5764-9dbd-e97a60bcb1a8"}, {"title": "叶昇在甘肃练兵", "description": "靖宁侯叶昇在甘肃训练军队。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年三月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4cba77c6-96e0-543f-928b-755ca1a80f08"}, {"title": "明廷赐许观等进士及第或出身", "description": "朝廷分别赐许观等人进士及第或出身。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年三月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "150cec4f-958c-5dd2-bd8a-d5f2aeefb2d3"}, {"title": "朱元璋册封十位皇子", "description": "朱元璋将十位皇子分别封为庆王、宁王、岷王、谷王、韩王、沈王、安王、唐王、郢王和伊王。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年四月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c9084e85-43e6-5846-a9d7-f44eacd31396"}, {"title": "燕王朱棣督军出塞并获胜", "description": "燕王朱棣督率傅友德等将领出塞，在击败对方后返回。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年四月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fb5dd02b-2543-5473-a860-85056e913c36"}, {"title": "汉王等六王在临清练兵", "description": "汉、卫、谷、庆、宁、岷六位藩王在临清训练军队。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年五月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "def2bded-ddeb-5a36-a785-6ee6c4a19b0e"}, {"title": "明廷命参照历代礼制改订生活礼规", "description": "朝廷命廷臣参照历代礼制，重新制定冠服、居室和器用的规例。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年六月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d257e958-8516-5dee-85d4-ca8c7a21a98b"}, {"title": "明廷因久旱复核囚案", "description": "因久旱未雨，明廷于六月甲子复核在押囚犯的案件。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年六月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3cc0d376-a9cf-5977-ae3e-7e948c1003ff"}, {"title": "明廷迁富户充实京师", "description": "朝廷将富户迁入京师。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年七月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94737343-a12b-5c06-85c3-7b7efdc30397"}, {"title": "明廷免征畿内官田一半租额", "description": "朝廷免去畿内官田租额的一半。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年七月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15aa923e-b305-54d5-9d4b-6bb1ad45ac34"}, {"title": "秦王朱樉获罪后被召回京师", "description": "秦王朱樉获罪，朝廷召他返回京师。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年八月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8b747f4f-81ff-5502-9939-d96a7f25cf11"}, {"title": "皇太子巡抚陕西", "description": "本纪记载，皇太子在八月乙丑巡抚陕西。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年八月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6a1b9a3c-7cd1-57dd-9c48-e186de403e05"}, {"title": "刘真和宋晟出讨哈梅里并获胜", "description": "都督佥事刘真、宋晟率军征讨哈梅里并击败对方。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年八月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d31e24ca-7966-5586-a4cd-893b890401d9"}, {"title": "明廷派使者前往西域传谕", "description": "朝廷派使者向西域传达谕令。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年九月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "af739a19-94e3-5e46-9956-aef3f742ec0f"}, {"title": "雷州遭倭寇，李玉陶鼎战死", "description": "这月倭寇进攻雷州，百户李玉和镇抚陶鼎在战事中阵亡。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3995ce81-5bf4-5eac-b2c9-438b40d051f0"}, {"title": "明廷免征北平河间受水灾地田租", "description": "朝廷免去北平、河间受水灾地方的田租。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "770943d4-724b-5aba-8f8d-ebb265c20651"}, {"title": "茅鼎率军平定五开战事", "description": "五开发生反抗，都督佥事茅鼎率军平定。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年十一月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f04bb276-d93d-5a3f-aca8-8c09b3c164ba"}, {"title": "皇太子返回京师，晋王朱棡来朝", "description": "本纪记载，皇太子回到京师，晋王朱棡同日入朝。", "start_year": 1391, "end_year": 1391, "time_original": "洪武二十四年十一月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fc3ec6a3-748c-5997-8acc-12b74dd813b1"}, {"title": "明廷赈济河南水灾", "description": "河南遭受水灾，明廷下令救济。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十四年十一月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f914150b-c645-558d-a4a1-a28975a8f53a"}, {"title": "周王朱橚返回封国", "description": "本纪记载，周王朱橚返回封国。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十四年十二月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4bfa4eeb-6748-5cdb-806e-639d2a9edfa5"}, {"title": "阿资再起兵，何福出讨并受降", "description": "阿资再次起兵反明，都督佥事何福出兵，迫使阿资投降。", "start_year": 1392, "end_year": 1392, "time_original": "洪武二十四年十二月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "63a4767e-6f13-5e95-af66-0b72cf885840"}, {"title": "明廷汇成各地赋役黄册", "description": "当年各地郡县的赋役黄册编成。本纪记全国合计一千零六十八万四千四百三十五户、五千六百七十七万四千五百六十一丁。 按原历纪年，事情发生在公元1391至1392年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7a222da-e1cf-5b58-830d-4134c568b702"}, {"title": "明廷因占城发生篡位事件拒收来贡", "description": "本纪记载，琉球、暹罗、别失八里和撒马儿罕入贡。明廷以占城发生篡位事件为由，拒收其来贡。 按原历纪年，事情发生在公元1391至1392年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "807f5b2e-a862-5877-977f-957b0cb24d93"}]'::jsonb)
